      SUBROUTINE MUNCHCC     CALCULATES EFFECT OF UNCERTAIN MISALIGNMENTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1C.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8E.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'SI.CIN'CC     LOCAL VARIABLESC      INTEGER         J, JKL, JPK, K, K2, KPJ      INTEGER         L1, L2, LL, M, MM, N      REAL            CTT(6,6), CT0P(3,3), CT0L(36), CT0PL(9),      1                CT1L(9)      REAL            GTL(180)      REAL            S, ZAP      EQUIVALENCE     (CT0(1,1),CT0L(1)), (CT0P(1,1),CT0PL(1)),      1                (CT1(1,1),CT1L(1))      EQUIVALENCE     (GT(1,1,1),GTL(1))CC----------------------------------------------------------------C     TRANSFORMATION OF COORDINATE SYSTEM BETWEEN MISALIGNMENTC     PIVOT AND EXIT FACEC      DO 5 J = 1, 9    5 CT1L(J) = 0.0      DO 8 J = 1, 36    8 CT0L(J) = 0.0      DO 9 J = 1, 9    9 CT0PL(J) = 0.0C      CALL OGET      CALL PIVENT      CALL PIVEXCC     TRANSFORMATION FROM MISALIGNMENT COORDINATES TO TRAJECTORYC     COORDINATES AT ENTRANCE FACEC      CT0P(1,2) = XT(3)      CT0P(2,1) = - CT0P(1,2)      CT0P(3,1) = XT(2)      CT0P(1,3) = - CT0P(3,1)      CT0P(2,3) = XT(1)      CT0P(3,2) = - CT0P(2,3)C      DO 110  J = 1, 3      DO 110  K = 1, 3      CT0(2*J-1,2*K-1) = OT(J,K)  110 CONTINUEC      DO 120 K = 1, 3      CT0(2,2*K) = OT(2,K)      CT0(4,2*K) = - OT(1,K)  120 CONTINUEC      DO 160 J = 1, 3      DO 160 K = 1, 3      S = 0.0      DO 150 N = 1, 3      S = S + CT0P(J,N)*OT(N,K)  150 CONTINUE      CT0(2*J-1,2*K)  =  S  160 CONTINUECC     TRANSFORMATION AT EXIT FACEC      CT1(1,2) = - XR(3)      CT1(2,1) = - CT1(1,2)      CT1(3,1) = - XR(2)      CT1(1,3) = - CT1(3,1)      CT1(2,3) = - XR(1)      CT1(3,2) = - CT1(2,3)CC     EFFECT OF MISALIGNMENT ON CENTROID DISPLACEMENTC  300 CALL TFLC      IF (IR .EQ. 1) CDB = 14      IF (IR .EQ. 2) CDB = 4      IF (IR .EQ. 3) CDB = 24      CALL RCALCCC     BILINEAR TERMSC      DO 320 JKL = 1, 180  320 GTL(JKL) = 0.0C      IF (NORD3 .LT. 1 .AND. .NOT. SPO(IR)) GO TO 400      DO 330 J = 1, 5      DO 325 K = 1, 6      GT(J,2,K) = RS(J,1)*CT0(5,K)      GT(J,4,K) = RS(J,3)*CT0(5,K)  325 CONTINUE      DO 327 K = 1, 3      K2 = 2*K      GT(J,1,K2) = - RS(J,3)*OT(3,K)      GT(J,2,K2) = GT(J,2,K2) - RS(J,4)*OT(3,K)      GT(J,3,K2) = RS(J,1)*OT(3,K)      GT(J,4,K2) = GT(J,4,K2) + RS(J,2)*OT(3,K)  327 CONTINUE  330 CONTINUEC      DO 360 J = 1, 6      DO 340 K = 1, 6      GT(1,J,K) = GT(1,J,K) - CT(5,K)*RS(2,J)      GT(3,J,K) = GT(3,J,K) - CT(5,K)*RS(4,J)  340 CONTINUE      DO 350 K = 1, 3      K2 = 2*K      GT(1,J,K2) = GT(1,J,K2) - OR(3,K)*RS(3,J)      GT(2,J,K2) = GT(2,J,K2) - OR(3,K)*RS(4,J)      GT(3,J,K2) = GT(3,J,K2) + OR(3,K)*RS(1,J)      GT(4,J,K2) = GT(4,J,K2) + OR(3,K)*RS(2,J)  350 CONTINUE  360 CONTINUECC     IMAGE OF DISPLACED CENTROID AT ENTRANCE FACEC  400 DO 420 J = 1, 6      DO 420 K = 1, 6      S = 0.0      DO 415 N = 1, 6      S = S + RS(J,N)*CT0(N,K)  415 CONTINUE      CTT(J,K) = CT(J,K)      CT(J,K) = CT(J,K) - S  420 CONTINUE      DO 460 J = 1, 6  460 CONTINUEC      IF (.NOT. SOFA) GO TO 470      DO 430 J = 1, 5      DO 425 K = 1, 6      CT(J,K) = CT(J,K) + RS(J,1)*CT0(5,K)*COLD(IR,2)      CT(J,K) = CT(J,K) + RS(J,3)*CT0(5,K)*COLD(IR,4)  425 CONTINUE      DO 427 K = 1, 3      K2 = 2*K      CT(J,K2) = CT(J,K2) - RS(J,3)*OT(3,K)*COLD(IR,1)      CT(J,K2) = CT(J,K2) - RS(J,4)*OT(3,K)*COLD(IR,2)      CT(J,K2) = CT(J,K2) + RS(J,1)*OT(3,K)*COLD(IR,3)      CT(J,K2) = CT(J,K2) + RS(J,2)*OT(3,K)*COLD(IR,4)  427 CONTINUE  430 CONTINUEC      DO 440 K = 1, 6      CT(1,K) = CT(1,K) - CTT(5,K)*CEN(2)      CT(3,K) = CT(3,K) - CTT(5,K)*CEN(4)  440 CONTINUE      DO 450 K = 1, 3      K2 = 2*K      CT(1,K2) = CT(1,K2) - OR(3,K)*CEN(3)      CT(2,K2) = CT(2,K2) - OR(3,K)*CEN(4)      CT(3,K2) = CT(3,K2) + OR(3,K)*CEN(1)      CT(4,K2) = CT(4,K2) + OR(3,K)*CEN(2)  450 CONTINUEC  470 IF (NORD1 .GT. 1) CALL FRAME2CC     UNCERTAINTY IN POSITION SHOWN IN BEAM MATRIXC  500 IF (LTAB .NE. 0) GO TO 600C      IF (NORD3 .LT. 1) GO TO 900      DO 550 J = 1, 5      DO 550 K = 1, J      S = 0.0      IF (FEO) GO TO 520      DO 510 N = 1, 6      ZAP = CT(J,N)*CT(K,N)*VM(N)**2      S = S + ZAP  510 CONTINUEC  520 IF (.NOT. SPO(IR)) GO TO 530      DO 525 LL = 1, 6      DO 525 M = 1, 6      ZAP = (CT(J,M)*GT(K,LL,M) + CT(K,M)*GT(J,LL,M))*COLD(IR,LL)*     1    VM(M)**2      S = S + ZAP  525 CONTINUEC  530 DO 535 L1 = 1, 6      DO 535 L2 = 1, 6      DO 535 M = 1, 6      ZAP = GT(J,L1,M)*GT(K,L2,M)*SIOL(IR,L1,L2)*VM(M)**2      S = S + ZAP  535 CONTINUE  540 SI(J,K) = SI(J,K) + S      SI(K,J) = SI(J,K)  550 CONTINUEC      RECENT = .FALSE.      NOPH = .FALSE.      GO TO 900CC     UNCERTAINTY IN POSITION SHOWN IN MISALIGNMENT TABLEC  600 LMIS(1,NM) = LUP(IR)      LMIS(2,NM) = LC      IF (.NOT. SOFA) THEN        DO 605 J = 1, 6        DO 605 M = 1, 6        COM(J,M,NM) = 0.0  605   CONTINUE      ELSE        DO 610 J = 1, 6        DO 610 M = 1, 6        COM(J,M,NM) = CO(J)  610   CONTINUE      ENDIFC  620 IF (NORD3 .LT. 1) GO TO 900      DO 650 J = 1, 6      DO 650 K = 1, J      JPK = 6*J + K - 6      KPJ = 6*K + J - 6      MM = 0      DO 650 M = 1, 6      MM = MM + M      S = 0.0      IF (J .LE. 5) THEN        IF (FEO) GO TO 630        S = CT(J,M)*CT(K,M)*VM(M)**2        IF (SPO(IR)) THEN          DO 625 LL = 1, 6          S = S + (CT(J,M)*GT(K,LL,M) + CT(K,M)*GT(J,LL,M))*     1        COLD(IR,LL)*VM(M)**2  625     CONTINUE        ENDIFC     630   DO 635 L1 = 1, 6        DO 635 L2 = 1, 6        S = S + GT(J,L1,M)*GT(K,L2,M)*SIOL(IR,L1,L2)*VM(M)**2  635   CONTINUE      ENDIF  640 SIM(JPK,M,NM) = SI(J,K) + S      SIM(KPJ,M,NM) = SIM(JPK,M,NM)  650 CONTINUEC  900 DMC = .FALSE.      RETURN      END